import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        String outputStr = "";
        int totalLength = inputStr.length();
        outputStr += inputStr.charAt(0);
        boolean replacedAtFlag = false;
        int position = 1;
        while (position < totalLength) {
            if (!replacedAtFlag && position < totalLength - 2 && inputStr.charAt(position) == 'a' && inputStr.charAt(position + 1) == 't') {
                outputStr += "@";
                replacedAtFlag = true;
                position++;
            } else if (position + 2 < totalLength && inputStr.substring(position, position + 3).equals("dot")) {
                outputStr += ".";
                position += 2;
            } else {
                outputStr += inputStr.charAt(position);
            }
            position++;
        }
        System.out.println(outputStr);
        scanner.close();
    }
}
